/* Experimental hosted C11 single-slot runtime. No Talven source support.
 * Callers supply aligned storage and keep every descriptor alive while its
 * published owner is live. Initialization starts a fresh logical origin lifetime;
 * do not reinitialize while earlier tokens are considered valid. Descriptor fields
 * are private runtime state apart from explicitly controlled trusted test probes.
 * Metadata is not a foreign-pointer security boundary.
 * TV_REGION_TEST_FAULT enables only trusted test instrumentation.
 */
#ifndef TALVEN_REGION_RUNTIME_V1_H
#define TALVEN_REGION_RUNTIME_V1_H
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    uint8_t *storage;
    size_t capacity;
    uint64_t instance;
    size_t live_size;
    size_t live_alignment;
    bool occupied;
} tv_region;

typedef struct {
    tv_region *origin;
    uint64_t instance;
    size_t length;
    size_t alignment;
} tv_block;

enum { TV_GRANTED = 0, TV_INVALID_REQUEST = 1, TV_EXHAUSTED = 2 };
typedef struct {
    uint32_t tag;
    union { tv_block block; } payload;
} tv_allocation;

enum { TV_READ_VALUE = 0, TV_READ_OUT_OF_BOUNDS = 1 };
typedef struct { uint32_t tag; int32_t value; } tv_byte_read;
enum { TV_WRITTEN = 0, TV_WRITE_OUT_OF_BOUNDS = 1, TV_INVALID_BYTE = 2 };

#ifdef TV_REGION_TEST_FAULT
extern bool tv_region_test_fault(uint32_t step);
#endif

static inline void tv_region_require(bool condition) {
    if (!condition) { abort(); }
}

static inline void tv_region_init(tv_region *region, uint8_t *storage, size_t capacity) {
    tv_region_require(region != NULL && storage != NULL);
    tv_region_require(capacity >= 1 && capacity <= 4096);
    tv_region_require(((uintptr_t)storage % 16) == 0);
    *region = (tv_region){.storage = storage, .capacity = capacity};
}

static inline tv_allocation tv_region_reserve(tv_region *region, int32_t size, int32_t alignment) {
    tv_region_require(region != NULL);
    if (size <= 0 || !(alignment == 1 || alignment == 2 || alignment == 4 ||
                      alignment == 8 || alignment == 16)) {
        return (tv_allocation){.tag = TV_INVALID_REQUEST};
    }
    if ((size_t)size > region->capacity || region->occupied || region->instance == UINT64_MAX) {
        return (tv_allocation){.tag = TV_EXHAUSTED};
    }
    region->instance += UINT64_C(1);
    region->occupied = true;
    region->live_size = (size_t)size;
    region->live_alignment = (size_t)alignment;
#ifdef TV_REGION_TEST_FAULT
    if (tv_region_test_fault(0)) { goto rollback; }
#endif
    for (size_t i = 0; i < (size_t)size; ++i) {
#ifdef TV_REGION_TEST_FAULT
        if (tv_region_test_fault((uint32_t)i + 1)) { goto rollback; }
#endif
        region->storage[i] = 0;
    }
#ifdef TV_REGION_TEST_FAULT
    if (tv_region_test_fault((uint32_t)size + 1)) { goto rollback; }
#endif
    return (tv_allocation){.tag = TV_GRANTED, .payload.block = {
        .origin = region, .instance = region->instance,
        .length = (size_t)size, .alignment = (size_t)alignment
    }};
#ifdef TV_REGION_TEST_FAULT
rollback:
    region->occupied = false;
    region->live_size = 0;
    region->live_alignment = 0;
    return (tv_allocation){.tag = TV_EXHAUSTED};
#endif
}

static inline tv_region *tv_region_owner(tv_block block) {
    tv_region_require(block.origin != NULL);
    tv_region *region = block.origin;
    tv_region_require(region->occupied && block.instance == region->instance &&
                      block.length == region->live_size && block.alignment == region->live_alignment);
    return region;
}

static inline int32_t tv_region_release(tv_block block) {
    tv_region *region = tv_region_owner(block);
    region->occupied = false;
    region->live_size = 0;
    region->live_alignment = 0;
    return 0;
}

static inline tv_byte_read tv_region_read(const tv_block *block, int32_t index) {
    tv_region_require(block != NULL);
    tv_region *region = tv_region_owner(*block);
    if (index < 0 || (size_t)index >= block->length) {
        return (tv_byte_read){.tag = TV_READ_OUT_OF_BOUNDS};
    }
    return (tv_byte_read){.tag = TV_READ_VALUE, .value = region->storage[(size_t)index]};
}

static inline uint32_t tv_region_write(tv_block *block, int32_t index, int32_t value) {
    tv_region_require(block != NULL);
    tv_region *region = tv_region_owner(*block);
    if (index < 0 || (size_t)index >= block->length) { return TV_WRITE_OUT_OF_BOUNDS; }
    if (value < 0 || value > 255) { return TV_INVALID_BYTE; }
    region->storage[(size_t)index] = (uint8_t)value;
    return TV_WRITTEN;
}
#endif

/* Experimental hosted C11 supplied-storage byte buffer. No Talven source support.
 * The block token, logical length and originating region are private runtime state.
 * Trusted C callers keep the descriptor and backing object alive, and transfer
 * rather than copy owners. Matching forged tokens are outside this boundary.
 */
#ifndef TALVEN_BYTE_BUFFER_RUNTIME_V1_H
#define TALVEN_BYTE_BUFFER_RUNTIME_V1_H
#include "../supplied-storage/runtime.h"

typedef struct {
    tv_block block;
    size_t length;
} tv_buffer;

typedef struct {
    uint32_t tag;
    union { tv_buffer buffer; } payload;
} tv_buffer_allocation;

enum { TV_BUFFER_PUSHED = 0, TV_BUFFER_FULL = 1, TV_BUFFER_INVALID_BYTE = 2 };
enum { TV_BUFFER_VALUE = 0, TV_BUFFER_EMPTY = 1 };
typedef struct { uint32_t tag; int32_t value; } tv_buffer_pop_result;

static inline tv_region *tv_buffer_owner(const tv_buffer *buffer) {
    tv_region_require(buffer != NULL);
    tv_region *region = tv_region_owner(buffer->block);
    tv_region_require(buffer->block.alignment == 1 && buffer->length <= buffer->block.length);
    return region;
}

static inline tv_buffer_allocation tv_buffer_reserve(tv_region *region, int32_t capacity) {
    tv_allocation allocation = tv_region_reserve(region, capacity, 1);
    if (allocation.tag != TV_GRANTED) {
        return (tv_buffer_allocation){.tag = allocation.tag};
    }
    return (tv_buffer_allocation){.tag = TV_GRANTED, .payload.buffer = {
        .block = allocation.payload.block, .length = 0
    }};
}

static inline int32_t tv_buffer_length(const tv_buffer *buffer) {
    (void)tv_buffer_owner(buffer);
    return (int32_t)buffer->length;
}

static inline int32_t tv_buffer_capacity(const tv_buffer *buffer) {
    (void)tv_buffer_owner(buffer);
    return (int32_t)buffer->block.length;
}

static inline tv_byte_read tv_buffer_read(const tv_buffer *buffer, int32_t index) {
    tv_region *region = tv_buffer_owner(buffer);
    if (index < 0 || (size_t)index >= buffer->length) {
        return (tv_byte_read){.tag = TV_READ_OUT_OF_BOUNDS};
    }
    return (tv_byte_read){.tag = TV_READ_VALUE, .value = region->storage[(size_t)index]};
}

static inline uint32_t tv_buffer_write(tv_buffer *buffer, int32_t index, int32_t value) {
    tv_region *region = tv_buffer_owner(buffer);
    if (index < 0 || (size_t)index >= buffer->length) { return TV_WRITE_OUT_OF_BOUNDS; }
    if (value < 0 || value > 255) { return TV_INVALID_BYTE; }
    region->storage[(size_t)index] = (uint8_t)value;
    return TV_WRITTEN;
}

static inline uint32_t tv_buffer_push(tv_buffer *buffer, int32_t value) {
    tv_region *region = tv_buffer_owner(buffer);
    if (buffer->length == buffer->block.length) { return TV_BUFFER_FULL; }
    if (value < 0 || value > 255) { return TV_BUFFER_INVALID_BYTE; }
    region->storage[buffer->length] = (uint8_t)value;
    buffer->length += 1;
    return TV_BUFFER_PUSHED;
}

static inline tv_buffer_pop_result tv_buffer_pop(tv_buffer *buffer) {
    tv_region *region = tv_buffer_owner(buffer);
    if (buffer->length == 0) { return (tv_buffer_pop_result){.tag = TV_BUFFER_EMPTY}; }
    int32_t value = region->storage[buffer->length - 1];
    buffer->length -= 1;
    return (tv_buffer_pop_result){.tag = TV_BUFFER_VALUE, .value = value};
}

static inline int32_t tv_buffer_close(tv_buffer buffer) {
    (void)tv_buffer_owner(&buffer);
    return tv_region_release(buffer.block);
}
#endif

/* Independent request-plan oracle for the internal C-only byte buffer. */
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include "../../experiments/byte-buffer/runtime.h"
#ifndef CAPACITY
#define CAPACITY 32
#endif
#define REQUIRE(x) do { if (!(x)) { fprintf(stderr, "oracle:%d\n", __LINE__); exit(41); } } while (0)
static int32_t fail_at = -1;
static uint32_t fault_calls;
bool tv_region_test_fault(uint32_t step) {
    REQUIRE(step == fault_calls);
    fault_calls++;
    return fail_at >= 0 && step == (uint32_t)fail_at;
}
typedef struct {
    uint8_t bytes[CAPACITY + 32];
    uint64_t epoch;
    bool live;
    size_t reserved, alignment, length;
    unsigned granted, released;
} ledger;
typedef struct {
    _Alignas(16) uint8_t storage[CAPACITY + 32];
    tv_region region;
    ledger expected;
} fixture;
static void observe(const fixture *f) {
    const ledger *m = &f->expected;
    REQUIRE(f->region.storage == f->storage + 16);
    REQUIRE(f->region.capacity == CAPACITY);
    REQUIRE(f->region.instance == m->epoch);
    REQUIRE(f->region.occupied == m->live);
    REQUIRE(f->region.live_size == m->reserved);
    REQUIRE(f->region.live_alignment == m->alignment);
    REQUIRE(memcmp(f->storage, m->bytes, sizeof(m->bytes)) == 0);
}
static void observe_buffer(const fixture *f, const tv_buffer *b) {
    observe(f);
    REQUIRE(f->expected.live);
    REQUIRE(b->block.origin == &f->region);
    REQUIRE(b->block.instance == f->expected.epoch);
    REQUIRE(b->block.length == f->expected.reserved);
    REQUIRE(b->block.alignment == 1);
    REQUIRE(b->length == f->expected.length);
}
static void fresh(fixture *f, uint64_t epoch) {
    memset(f->storage, 0xa5, sizeof(f->storage));
    f->expected = (ledger){.epoch = epoch};
    memset(f->expected.bytes, 0xa5, sizeof(f->expected.bytes));
    tv_region_init(&f->region, f->storage + 16, CAPACITY);
    /* Explicit trusted saturation injection; never an observed oracle input. */
    f->region.instance = epoch;
    observe(f);
}
static uint32_t planned_reserve(fixture *f, int32_t size, int32_t alignment) {
    ledger *m = &f->expected;
    bool valid = size > 0 && (alignment == 1 || alignment == 2 || alignment == 4 || alignment == 8 || alignment == 16);
    bool space = valid && (size_t)size <= CAPACITY && !m->live && m->epoch != UINT64_MAX;
    uint32_t tag = !valid ? 1 : !space ? 2 : 0;
    fault_calls = 0;
    if (space) {
        m->epoch++;
        bool failed = false;
#ifdef TV_REGION_TEST_FAULT
        failed = fail_at >= 0 && fail_at <= size + 1;
#endif
        size_t initialized = failed ? (fail_at <= 1 ? 0 : (size_t)fail_at - 1) : (size_t)size;
        memset(m->bytes + 16, 0, initialized);
        if (failed) { tag = 2; }
        else {
            m->live = true;
            m->reserved = (size_t)size;
            m->alignment = (size_t)alignment;
            m->length = 0;
            m->granted++;
        }
    }
    return tag;
}
static void check_faults(uint32_t tag, bool attempted, int32_t size) {
#ifdef TV_REGION_TEST_FAULT
    REQUIRE(fault_calls == (!attempted ? 0 : tag == 0 ? (uint32_t)size + 2 : (uint32_t)fail_at + 1));
#else
    (void)tag; (void)attempted; (void)size;
    REQUIRE(fault_calls == 0);
#endif
}
static tv_buffer_allocation reserve_buffer(fixture *f, int32_t capacity) {
    bool attempted = capacity > 0 && capacity <= CAPACITY && !f->expected.live && f->expected.epoch != UINT64_MAX;
    uint32_t expected = planned_reserve(f, capacity, 1);
    tv_buffer_allocation result = tv_buffer_reserve(&f->region, capacity);
    REQUIRE(result.tag == expected);
    check_faults(expected, attempted, capacity);
    observe(f);
    if (expected == 0) { observe_buffer(f, &result.payload.buffer); }
    return result;
}
static tv_allocation reserve_block(fixture *f, int32_t size, int32_t alignment) {
    bool attempted = size > 0 && size <= CAPACITY && !f->expected.live && f->expected.epoch != UINT64_MAX && (alignment == 1 || alignment == 2 || alignment == 4 || alignment == 8 || alignment == 16);
    uint32_t expected = planned_reserve(f, size, alignment);
    tv_allocation result = tv_region_reserve(&f->region, size, alignment);
    REQUIRE(result.tag == expected);
    check_faults(expected, attempted, size);
    observe(f);
    if (expected == 0) {
        REQUIRE(result.payload.block.origin == &f->region);
        REQUIRE(result.payload.block.instance == f->expected.epoch);
        REQUIRE(result.payload.block.length == f->expected.reserved);
        REQUIRE(result.payload.block.alignment == f->expected.alignment);
    }
    return result;
}
static void retired(fixture *f) {
    f->expected.live = false;
    f->expected.reserved = f->expected.alignment = f->expected.length = 0;
    f->expected.released++;
    observe(f);
}
static void close_buffer(fixture *f, tv_buffer b) {
    observe_buffer(f, &b);
    REQUIRE(tv_buffer_close(b) == 0);
    retired(f);
}
static void queries(fixture *f, const tv_buffer *b) {
    REQUIRE(tv_buffer_length(b) == (int32_t)f->expected.length);
    observe_buffer(f, b);
    REQUIRE(tv_buffer_capacity(b) == (int32_t)f->expected.reserved);
    observe_buffer(f, b);
}
static void read_buffer(fixture *f, const tv_buffer *b, int32_t index) {
    bool valid = index >= 0 && (size_t)index < f->expected.length;
    tv_byte_read result = tv_buffer_read(b, index);
    REQUIRE(result.tag == (valid ? 0u : 1u));
    if (valid) { REQUIRE(result.value == f->expected.bytes[16 + (size_t)index]); }
    observe_buffer(f, b);
}
static void write_buffer(fixture *f, tv_buffer *b, int32_t index, int32_t value) {
    uint32_t expected = index < 0 || (size_t)index >= f->expected.length ? 1 : value < 0 || value > 255 ? 2 : 0;
    if (expected == 0) { f->expected.bytes[16 + (size_t)index] = (uint8_t)value; }
    REQUIRE(tv_buffer_write(b, index, value) == expected);
    observe_buffer(f, b);
    queries(f, b);
}
static void push(fixture *f, tv_buffer *b, int32_t value) {
    uint32_t expected = f->expected.length == f->expected.reserved ? 1 : value < 0 || value > 255 ? 2 : 0;
    if (expected == 0) {
        f->expected.bytes[16 + f->expected.length] = (uint8_t)value;
        f->expected.length++;
    }
    REQUIRE(tv_buffer_push(b, value) == expected);
    observe_buffer(f, b);
    queries(f, b);
}
static void pop(fixture *f, tv_buffer *b) {
    bool nonempty = f->expected.length != 0;
    int32_t value = nonempty ? f->expected.bytes[16 + f->expected.length - 1] : 0;
    if (nonempty) { f->expected.length--; }
    tv_buffer_pop_result result = tv_buffer_pop(b);
    REQUIRE(result.tag == (nonempty ? 0u : 1u));
    if (nonempty) { REQUIRE(result.value == value); }
    observe_buffer(f, b);
    queries(f, b);
}
static void accesses(fixture *f, tv_buffer *b) {
    int32_t indices[] = {INT32_MIN, -1, 0, (int32_t)f->expected.length - 1,
                         (int32_t)f->expected.length, (int32_t)f->expected.reserved, INT32_MAX};
    int32_t values[] = {INT32_MIN, -1, 0, 1, 254, 255, 256, INT32_MAX};
    for (size_t i = 0; i < sizeof(indices)/sizeof(indices[0]); i++) {
        for (size_t v = 0; v < sizeof(values)/sizeof(values[0]); v++) {
            write_buffer(f, b, indices[i], values[v]);
            read_buffer(f, b, indices[i]);
        }
    }
}
static void transitions(fixture *f, tv_buffer *b) {
    queries(f, b);
    pop(f, b);
    accesses(f, b);
    push(f, b, INT32_MIN);
    push(f, b, -1);
    push(f, b, 256);
    push(f, b, INT32_MAX);
    for (unsigned round = 0; round < 3; round++) {
        size_t reserved = f->expected.reserved;
        for (size_t i = 0; i < reserved; i++) {
            push(f, b, (int32_t)((i * 37 + round * 83) % 256));
            read_buffer(f, b, (int32_t)i);
            read_buffer(f, b, (int32_t)i + 1);
        }
        accesses(f, b);
        push(f, b, 0);
        push(f, b, -1); /* Full precedes invalid byte. */
        push(f, b, 256);
        push(f, b, INT32_MAX);
        for (size_t i = 0; i < reserved; i++) {
            pop(f, b);
            read_buffer(f, b, (int32_t)f->expected.length); /* Retired byte inaccessible. */
        }
        pop(f, b);
    }
    /* All byte values, even when the backing capacity is one. */
    for (int32_t value = 0; value <= 255; value++) { push(f, b, value); read_buffer(f, b, 0); pop(f, b); }
}
static void complete(fixture *f) {
    REQUIRE(!f->expected.live && f->expected.granted == f->expected.released);
    observe(f);
}
static int probe(fixture *f, const char *name) {
    const char *names[] = {"stale", "double", "length", "block-capacity", "alignment", "instance",
                          "read-closed", "write-closed", "push-closed", "pop-closed", "length-closed", "capacity-closed"};
    bool known = false;
    for (size_t i = 0; i < sizeof(names)/sizeof(names[0]); i++) { if (strcmp(name, names[i]) == 0) { known = true; } }
    if (!known) { return 42; }
    fresh(f, 0);
    if (strcmp(name, "alignment") == 0) {
        tv_block aligned = reserve_block(f, 1, 2).payload.block;
        tv_buffer wrapped = {.block = aligned, .length = 0};
        (void)tv_buffer_push(&wrapped, 0);
        return 0;
    }
    tv_buffer b = reserve_buffer(f, 1).payload.buffer;
    if (strcmp(name, "stale") == 0) { close_buffer(f, b); (void)reserve_buffer(f, 1); (void)tv_buffer_close(b); }
    else if (strcmp(name, "double") == 0) { close_buffer(f, b); (void)tv_buffer_close(b); }
    else if (strcmp(name, "length") == 0) { b.length = 2; (void)tv_buffer_length(&b); }
    else if (strcmp(name, "block-capacity") == 0) { b.block.length = 2; (void)tv_buffer_capacity(&b); }
    else if (strcmp(name, "instance") == 0) { b.block.instance = 0; (void)tv_buffer_pop(&b); }
    else {
        close_buffer(f, b);
        if (strcmp(name, "read-closed") == 0) { (void)tv_buffer_read(&b, 0); }
        else if (strcmp(name, "write-closed") == 0) { (void)tv_buffer_write(&b, 0, 0); }
        else if (strcmp(name, "push-closed") == 0) { (void)tv_buffer_push(&b, 0); }
        else if (strcmp(name, "pop-closed") == 0) { (void)tv_buffer_pop(&b); }
        else if (strcmp(name, "length-closed") == 0) { (void)tv_buffer_length(&b); }
        else { (void)tv_buffer_capacity(&b); }
    }
    return 0;
}
int main(int argc, char **argv) {
    fixture f;
    REQUIRE(TV_BUFFER_PUSHED == 0 && TV_BUFFER_FULL == 1 && TV_BUFFER_INVALID_BYTE == 2);
    REQUIRE(TV_BUFFER_VALUE == 0 && TV_BUFFER_EMPTY == 1);
    if (argc > 1) { return probe(&f, argv[1]); }
    int32_t capacities[] = {INT32_MIN, -1, 0, 1, CAPACITY, CAPACITY + 1, INT32_MAX};
    for (size_t i = 0; i < sizeof(capacities)/sizeof(capacities[0]); i++) {
        fresh(&f, 0);
        tv_buffer_allocation allocation = reserve_buffer(&f, capacities[i]);
        if (allocation.tag == 0) {
            tv_buffer b = allocation.payload.buffer;
            transitions(&f, &b);
            (void)reserve_buffer(&f, 1);
            (void)reserve_buffer(&f, 0);
            (void)reserve_block(&f, 1, 1);
            (void)reserve_block(&f, 0, 1);
            close_buffer(&f, b);
        }
        tv_buffer reuse = reserve_buffer(&f, 1).payload.buffer;
        close_buffer(&f, reuse);
        complete(&f);
    }
    fresh(&f, 0);
    tv_block block = reserve_block(&f, CAPACITY, 1).payload.block;
    REQUIRE(tv_region_write(&block, 0, 219) == 0);
    f.expected.bytes[16] = 219;
    observe(&f);
    (void)reserve_buffer(&f, CAPACITY);
    (void)reserve_buffer(&f, -1);
    REQUIRE(tv_region_release(block) == 0);
    retired(&f);
    tv_buffer mixed = reserve_buffer(&f, CAPACITY).payload.buffer;
    close_buffer(&f, mixed);
    complete(&f);
#ifdef TV_REGION_TEST_FAULT
    int32_t sizes[] = {1, CAPACITY};
    for (size_t n = 0; n < sizeof(sizes)/sizeof(sizes[0]); n++) {
        for (int32_t fault = 0; fault <= sizes[n] + 1; fault++) {
            fresh(&f, 0);
            fail_at = fault;
            REQUIRE(reserve_buffer(&f, sizes[n]).tag == 2);
            REQUIRE(!f.expected.live && f.expected.epoch == 1);
            fail_at = -1;
            tv_buffer retry = reserve_buffer(&f, sizes[n]).payload.buffer;
            push(&f, &retry, 255);
            pop(&f, &retry);
            close_buffer(&f, retry);
            REQUIRE(f.expected.epoch == 2);
            complete(&f);
        }
    }
    fresh(&f, UINT64_MAX - 1);
    fail_at = 1;
    REQUIRE(reserve_buffer(&f, 1).tag == 2);
    fail_at = -1;
    REQUIRE(reserve_buffer(&f, 1).tag == 2);
    REQUIRE(f.expected.epoch == UINT64_MAX);
    complete(&f);
#endif
    fresh(&f, UINT64_MAX);
    REQUIRE(reserve_buffer(&f, 1).tag == 2);
    REQUIRE(reserve_buffer(&f, 0).tag == 1);
    complete(&f);
    fresh(&f, UINT64_MAX - 1);
    tv_buffer last = reserve_buffer(&f, 1).payload.buffer;
    push(&f, &last, 128);
    close_buffer(&f, last);
    REQUIRE(reserve_buffer(&f, 1).tag == 2);
    complete(&f);
    printf("{\"capacity\":%d,\"descriptor_bytes\":%zu,\"block_bytes\":%zu,\"buffer_bytes\":%zu,\"allocation_bytes\":%zu,\"pop_result_bytes\":%zu}\n",
           CAPACITY, sizeof(tv_region), sizeof(tv_block), sizeof(tv_buffer), sizeof(tv_buffer_allocation), sizeof(tv_buffer_pop_result));
    return 0;
}

#!/usr/bin/env python3
"""Verify the C-only supplied byte buffer against an independent request ledger."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import resource
import shutil
import signal
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[1]
SOURCES = ('experiments/supplied-storage/runtime.h', 'experiments/byte-buffer/runtime.h',
           'tests/fixtures/byte-buffer-driver.c', 'scripts/check-byte-buffer-runtime.py',
           'tests/test_byte_buffer_runtime.py')
PROBES = ('stale', 'double', 'length', 'block-capacity', 'alignment', 'instance',
          'read-closed', 'write-closed', 'push-closed', 'pop-closed', 'length-closed', 'capacity-closed')
FLAGS = ['-std=c11', '-Wall', '-Wextra', '-Werror', '-pedantic-errors']
SANITIZERS = ['-fsanitize=address,undefined', '-fno-sanitize-recover=all']
PERMITTED = {'abort', 'bzero', 'memcpy', 'memmove', 'memset', 'stack_chk_fail',
             'stack_chk_guard', 'chkstk_darwin', 'GLOBAL_OFFSET_TABLE_'}
WRAPPER = '''#include "experiments/byte-buffer/runtime.h"
void init(tv_region *r, uint8_t *s, size_t n) { tv_region_init(r,s,n); }
tv_buffer_allocation reserve(tv_region *r, int32_t n) { return tv_buffer_reserve(r,n); }
int32_t length(const tv_buffer *b) { return tv_buffer_length(b); }
int32_t capacity(const tv_buffer *b) { return tv_buffer_capacity(b); }
tv_byte_read read_byte(const tv_buffer *b, int32_t i) { return tv_buffer_read(b,i); }
uint32_t write_byte(tv_buffer *b, int32_t i, int32_t v) { return tv_buffer_write(b,i,v); }
uint32_t push(tv_buffer *b, int32_t v) { return tv_buffer_push(b,v); }
tv_buffer_pop_result pop(tv_buffer *b) { return tv_buffer_pop(b); }
int32_t close_buffer(tv_buffer b) { return tv_buffer_close(b); }
'''


def require(condition, message):
    if not condition:
        raise RuntimeError(message)


def fingerprint(path):
    data = Path(path).read_bytes()
    return {'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}


def check_bytes(path, expected):
    require(Path(path).read_bytes() == expected, 'Observed gate input change: ' + str(path))


def check_artifacts(artifacts):
    for path, expected in artifacts.items():
        require(fingerprint(path) == expected, 'Observed compiled artifact change: ' + str(path))


def strict_json(text):
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, 'Duplicate JSON key')
            result[key] = value
        return result
    return json.loads(text, object_pairs_hook=pairs,
                      parse_constant=lambda value: (_ for _ in ()).throw(RuntimeError('Nonfinite JSON value: ' + value)))


def layout(output, capacity):
    result = strict_json(output)
    keys = {'capacity', 'descriptor_bytes', 'block_bytes', 'buffer_bytes', 'allocation_bytes', 'pop_result_bytes'}
    require(type(result) is dict and set(result) == keys, 'Unexpected byte-buffer layout shape')
    require(all(type(result[key]) is int and result[key] > 0 for key in keys), 'Invalid measured C layout')
    require(result['capacity'] == capacity, 'Incorrect layout capacity')
    return result


def undefined_symbols(output, system):
    symbols = []
    # GNU nm emits U symbol; Darwin nm -u also permits a bare underscored symbol.
    linux_names = {name: name for name in PERMITTED}
    linux_names.update({'__stack_chk_fail': 'stack_chk_fail', '__stack_chk_guard': 'stack_chk_guard',
                        '_GLOBAL_OFFSET_TABLE_': 'GLOBAL_OFFSET_TABLE_'})
    darwin_names = {'_' + name: name for name in PERMITTED}
    darwin_names.update({'___stack_chk_fail': 'stack_chk_fail', '___stack_chk_guard': 'stack_chk_guard',
                         '___chkstk_darwin': 'chkstk_darwin'})
    allowed = darwin_names if system == 'Darwin' else linux_names
    for line in output.splitlines():
        if not line.strip():
            continue
        match = re.fullmatch(r'\s*U\s+(\S+)\s*', line)
        if match:
            raw = match.group(1)
        elif system == 'Darwin' and re.fullmatch(r'\s*_[A-Za-z_0-9]+\s*', line):
            raw = line.strip()
        else:
            raise RuntimeError('Unrecognized nm undefined-symbol row: ' + line)
        require(raw in allowed, 'Unapproved production dependency: ' + raw)
        symbols.append(allowed[raw])
    return sorted(set(symbols))


def accept_trap(result, probe):
    require(result['returncode'] == -signal.SIGABRT, 'Contract probe did not SIGABRT: ' + probe)
    require(not result['stdout'], 'Contract probe emitted unexpected stdout: ' + probe)
    require(not any(marker in result['stderr'] for marker in ('oracle:', 'AddressSanitizer', 'UndefinedBehaviorSanitizer', 'runtime error:')),
            'Contract probe had oracle/sanitizer failure: ' + probe)


def arch(value):
    return {'arm64': 'aarch64', 'amd64': 'x86_64'}.get(value.lower(), value.lower())


def verify():
    system = platform.system()
    native_arch = arch(platform.machine())
    require(system in ('Linux', 'Darwin') and native_arch in ('x86_64', 'aarch64'),
            'Unsupported actual host; this gate never skips acceptance')
    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    captured = {name: (ROOT / name).read_bytes() for name in SOURCES}
    report = {'schema': 'talven.byte-buffer-runtime-check.v1', 'profile': 'c11-supplied-byte-buffer-v1',
              'validation': 'C-runtime-only; no Talven lifetime checking', 'ok': False,
              'complete': False, 'passed': False, 'commands': [], 'executions': [], 'abort_probes': [],
              'inputs': [{'path': name, 'text': data.decode('utf-8'), 'sha256': hashlib.sha256(data).hexdigest()}
                         for name, data in captured.items()], 'tools': {}, 'artifacts': []}
    tools = {}
    for name in ('cc', 'nm', 'uname'):
        value = shutil.which(name)
        require(value is not None, 'Required tool missing: ' + name)
        tools[name] = Path(value).resolve()
    tools['python'] = Path(sys.executable).resolve()
    if system == 'Darwin':
        tools['sysctl'] = Path('/usr/sbin/sysctl').resolve()
    initial = {name: fingerprint(path) for name, path in tools.items()}
    artifacts = {}
    stable = {ROOT / name: data for name, data in captured.items()}

    def run(command, timeout=30, success=True):
        for path, data in stable.items():
            check_bytes(path, data)
        check_artifacts(artifacts)
        used_tool = next((name for name, path in tools.items() if str(path) == str(command[0])), None)
        if used_tool is not None:
            require(fingerprint(tools[used_tool]) == initial[used_tool], 'Tool executable changed before use: ' + used_tool)
        result = subprocess.run([str(part) for part in command], capture_output=True, text=True, timeout=timeout)
        if used_tool is not None:
            require(fingerprint(tools[used_tool]) == initial[used_tool], 'Tool executable changed after use: ' + used_tool)
        record = {'command': [str(part) for part in command], 'stdout': result.stdout,
                  'stderr': result.stderr, 'returncode': result.returncode,
                  'tool': None if used_tool is None else {'name': used_tool, **initial[used_tool]}}
        report['commands'].append(record)
        for path, data in stable.items():
            check_bytes(path, data)
        check_artifacts(artifacts)
        if success:
            require(result.returncode == 0, 'Trusted command failed: ' + result.stderr + result.stdout)
        return record

    dispatch = {}
    sdk = None
    platform_flags = []
    if system == 'Darwin':
        for name in ('cc', 'nm'):
            if tools[name] == Path('/usr/bin') / name:
                resolver = Path('/usr/bin/xcrun')
                require(resolver.is_file(), 'Darwin effective-tool resolver missing')
                if 'xcrun' not in tools:
                    tools['xcrun'] = resolver
                    initial['xcrun'] = fingerprint(resolver)
                value = run([resolver, '--find', name])['stdout'].strip()
                effective = Path(value)
                require('\n' not in value and effective.is_absolute() and effective.is_file() and os.access(effective, os.X_OK),
                        'Invalid Darwin effective tool')
                effective = effective.resolve()
                dispatch[name] = {'invocation': str(tools[name]), 'effective': str(effective)}
                tools[name + '_dispatch_wrapper'] = tools[name]
                initial[name + '_dispatch_wrapper'] = initial[name]
                tools[name] = effective
                initial[name] = fingerprint(effective)
        if 'cc' in dispatch:
            path = run([tools['xcrun'], '--sdk', 'macosx', '--show-sdk-path'])['stdout'].strip()
            version = run([tools['xcrun'], '--sdk', 'macosx', '--show-sdk-version'])['stdout'].strip()
            require('\n' not in path and Path(path).is_dir() and version and '\n' not in version, 'Invalid Darwin SDK selection')
            settings_path = Path(path) / 'SDKSettings.json'
            settings = settings_path.read_bytes() if settings_path.is_file() else None
            sdk = {'path': path, 'version': version, 'settings': None if settings is None else {
                'path': str(settings_path), 'text': settings.decode('utf-8'), 'sha256': hashlib.sha256(settings).hexdigest()},
                'closure_note': 'Full SDK/header/linker closure is not archived or verified'}
            if settings is not None:
                stable[settings_path] = settings
            platform_flags = ['-isysroot', path]
    for name, path in tools.items():
        report['tools'][name] = {'path': str(path), 'initial': initial[name]}
    for name in ('cc', 'nm', 'python'):
        report['tools'][name]['version'] = run([tools[name], '--version'])['stdout']
        require(report['tools'][name]['version'].strip(), 'Empty tool version')
    target = run([tools['cc'], '-dumpmachine'])['stdout'].strip()
    require(target and '\n' not in target and arch(target.split('-')[0]) == native_arch, 'C target differs from native host architecture')
    require(('darwin' in target.lower()) if system == 'Darwin' else ('linux' in target.lower()), 'C target differs from native host system')
    uname = run([tools['uname'], '-m'])['stdout'].strip()
    require(arch(uname) == native_arch, 'Actual uname host differs from declared host')
    if system == 'Darwin':
        underlying_arm = run([tools['sysctl'], '-n', 'hw.optional.arm64'])['stdout'].strip()
        require(underlying_arm in ('0', '1'), 'Unknown Darwin native CPU evidence')
        require(underlying_arm != '1' or native_arch == 'aarch64', 'Emulated Darwin process is not native host evidence')
    report['environment'] = {'system': system, 'release': platform.release(), 'machine': platform.machine(),
                             'native_arch': native_arch, 'uname_machine': uname, 'logical_cpus': os.cpu_count(),
                             'c_target': target, 'platform_flags': platform_flags,
                             'darwin_dispatch': dispatch, 'sdk': sdk}
    with tempfile.TemporaryDirectory(prefix='talven-byte-buffer-') as temporary:
        directory = Path(temporary)
        for name, data in captured.items():
            path = directory / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            stable[path] = data
        driver = directory / SOURCES[2]
        # Compile-time target evidence independently checks the selected tool's macros.
        target_check = directory / 'target.c'
        macro = '__aarch64__' if native_arch == 'aarch64' else '__x86_64__'
        target_check.write_text('#ifndef ' + macro + '\n#error "C target is not actual host"\n#endif\nint target_check(void) { return 0; }\n')
        stable[target_check] = target_check.read_bytes()
        target_obj = directory / 'target.o'
        run([tools['cc'], *FLAGS, *platform_flags, '-c', target_check, '-o', target_obj])
        artifacts[target_obj] = fingerprint(target_obj)
        for capacity in (1, 32, 4096):
            for optimization in ('-O0', '-O2'):
                for fault in (False, True):
                    flags = [*FLAGS, *platform_flags, optimization, *SANITIZERS, f'-DCAPACITY={capacity}']
                    if fault:
                        flags.append('-DTV_REGION_TEST_FAULT')
                    executable = directory / f'check-{capacity}-{optimization[1:]}-{int(fault)}'
                    run([tools['cc'], *flags, driver, '-o', executable])
                    artifacts[executable] = fingerprint(executable)
                    positive = run([executable])
                    require(not positive['stderr'], 'Independent ledger emitted diagnostics')
                    measured = layout(positive['stdout'], capacity)
                    probes = []
                    for probe in PROBES:
                        result = run([executable, probe], timeout=5, success=False)
                        accept_trap(result, probe)
                        report['abort_probes'].append({'probe': probe, 'flags': flags, 'result': result})
                        probes.append(probe)
                    report['executions'].append({'flags': flags, 'fault_injection': fault, 'layout': measured,
                                                 'ledger_passed': True, 'abort_probes': probes})
                    if capacity == 1 and optimization == '-O0' and not fault:
                        unknown = run([executable, 'unknown-probe'], success=False)
                        require(unknown['returncode'] == 42 and not unknown['stdout'] and not unknown['stderr'], 'Unknown probe classification failed')
                        report['unknown_probe'] = unknown
        wrapper = directory / 'production.c'
        wrapper.write_text(WRAPPER)
        stable[wrapper] = WRAPPER.encode('utf-8')
        obj = directory / 'production.o'
        production_flags = [*FLAGS, *platform_flags, '-O2']
        run([tools['cc'], *production_flags, '-c', wrapper, '-o', obj])
        artifacts[obj] = fingerprint(obj)
        symbols = undefined_symbols(run([tools['nm'], '-u', obj])['stdout'], system)
        report['production'] = {'flags': production_flags, 'wrapper': WRAPPER,
                                'wrapper_sha256': hashlib.sha256(WRAPPER.encode()).hexdigest(),
                                'undefined_symbols': symbols, 'permitted_symbols': sorted(PERMITTED),
                                'dependency_scope': 'this object; excludes hosted startup/libc internals'}
        for name, entry in dispatch.items():
            require(str(Path(run([tools['xcrun'], '--find', name])['stdout'].strip()).resolve()) == entry['effective'], 'Effective tool selection changed')
        if sdk is not None:
            require(run([tools['xcrun'], '--sdk', 'macosx', '--show-sdk-path'])['stdout'].strip() == sdk['path'], 'SDK path changed')
            require(run([tools['xcrun'], '--sdk', 'macosx', '--show-sdk-version'])['stdout'].strip() == sdk['version'], 'SDK version changed')
            require(sdk['settings'] is not None or not (Path(sdk['path']) / 'SDKSettings.json').is_file(), 'SDK settings appeared during run')
        for name, path in tools.items():
            final = fingerprint(path)
            require(final == initial[name], 'Tool executable changed: ' + name)
            report['tools'][name]['final'] = final
        for name in ('cc', 'nm', 'python'):
            final_version = run([tools[name], '--version'])['stdout']
            require(final_version == report['tools'][name]['version'], 'Tool version changed: ' + name)
        require(run([tools['cc'], '-dumpmachine'])['stdout'].strip() == target, 'C target changed')
        for path, data in stable.items():
            check_bytes(path, data)
        check_artifacts(artifacts)
        for name, path in tools.items():
            final = fingerprint(path)
            require(final == initial[name], 'Tool executable changed at completion: ' + name)
            report['tools'][name]['final'] = final
        report['artifacts'] = [{'path': str(path.relative_to(directory)), 'initial': identity, 'final': fingerprint(path)}
                               for path, identity in artifacts.items()]
    report.update(ok=True, complete=True, passed=True, positive_executions=len(report['executions']),
                  negative_trap_executions=len(report['abort_probes']))
    report['limits'] = ['C-only experiment; no source move/loan/close enforcement',
                        'Layout excludes backing capacity, padding outside descriptors, live copies and test ledger',
                        'No timing, total RAM, whole-stack, p99, agent-cost or broader container/concurrency claim',
                        'Exact inputs and compiled artifact identities recorded; temporary artifacts are not retained',
                        'Trusted tools and host required; executable hashes do not capture transitive toolchain dependencies']
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', type=Path, help='Create a new JSON receipt; default stdout')
    args = parser.parse_args()
    if args.out and args.out.exists():
        parser.error('--out must be a new file')
    report = verify()
    data = json.dumps(report, sort_keys=True, indent=2) + '\n'
    if args.out:
        args.out.parent.mkdir(parents=True, exist_ok=True)
        with args.out.open('x', encoding='utf-8') as output:
            output.write(data)
    else:
        print(data, end='')


if __name__ == '__main__':
    main()

